_offset +\n        tl.max_contiguous(tl.multiple_of(offset_m % cta_m_len, BLOCK_M),\n                          BLOCK_M))\n\n    do_expand_kernel(\n        pid_n,\n        lora_index,\n        slice_id,\n        input_ptr,\n        lora_ptr,\n        out_ptr,\n        curr_N,\n        K,\n        cta_m_len,\n        ram,\n        slice_start_loc,\n        # input ptr strides\n        input_d0_stride,\n        input_d1_stride,\n        input_d2_stride,\n        # lora ptr strides\n        ls_d0_ptr,\n        ls_d1_ptr,\n        ls_d2_ptr,\n        # out ptr strides\n        output_d0_stride,\n        output_d1_stride,\n        # constants\n        BLOCK_M,\n        BLOCK_N,\n        BLOCK_K,\n        SAME_STRIDE,\n        SLICE_NUM,\n        EVEN_K,\n        CAST_TYPE,\n        ADD_INPUTS,\n    )",
        "_v1_expand": "@torch.inference_mode()\ndef _v1_expand(\n    inputs: torch.Tensor,  # shape [num_slices, num_tokens, lora_rank]\n    lora_b_weights: List[\n        torch.Tensor],  # shape [num_lora, hidden_size, lora_rank]\n    output_tensor: torch.\n    Tensor,  # shape [num_tokens, hidden_size * num_slices]\n    token_lora_mapping: torch.Tensor,  # shape [num_tokens]\n    token_indices_sorted_by_lora_ids: torch.Tensor,  # shape [num_tokens]\n    num_tokens_per_lora: torch.Tensor,  # shape [max-loras + 1]\n    lora_token_start_loc: torch.Tensor,  # shape [max-loras + 2]\n    lora_ids: torch.Tensor,  # shape [max-loras + 1]\n    offset_start: int = 0,\n    add_inputs: bool = False,\n) -> None:\n    assert inputs.dtype in [torch.float16, torch.bfloat16, torch.float32]\n    for weight in lora_b_weights:\n        assert weight.dtype in [torch.float16, torch.bfloat16]\n\n    num_tokens = token_lora_mapping.size(0)\n    assert inputs.size(1) == num_tokens\n    assert inputs.size(0) == len(lora_b_weights)\n\n    assert output_tensor.is_contiguous()\n    (slice_start_tensor, lora_ptr_tensor, lora_strides_d0_tensor,\n     lora_strides_d1_tensor, lora_strides_d2_tensor, hidden_sizes_tensor,\n     same_stride, MAX_N) = _get_lora_b_ptr(lora_b_weights, offset_start,\n                                           inputs.device)\n\n    K = lora_b_weights[0].shape[-1]  # K= rank\n\n    BLOCK_M = 64\n    BLOCK_N = 128\n    BLOCK_K = 16\n    EVEN_K = K % BLOCK_K == 0\n    ADD_INPUTS = add_inputs\n    CAST_TYPE = False\n\n    if inputs.dtype == torch.float32 and lora_b_weights[0].dtype in [\n            torch.float16,\n            torch.bfloat16,\n    ]:\n        CAST_TYPE = True\n\n    # grid: (max_tokens_per_lora / BLOCK_M * MAX_N / BLOCK_N, num_loras, num_slices)\n    # We use a conservative grid size for the first dimension\n    max_tokens_per_lora = torch.max(num_tokens_per_lora).item()\n    grid = (\n        triton.cdiv(max_tokens_per_lora, BLOCK_M) * triton.cdiv(MAX_N, BLOCK_N),\n        lora_ids.size(0),\n        len(lora_b_weights),\n    )\n\n    _v1_expand_kernel[grid](\n        inputs,\n        lora_ptr_tensor,\n        output_tensor,\n        num_tokens,\n        MAX_N,\n        K,\n        token_indices_sorted_by_lora_ids,\n        num_tokens_per_lora,\n        lora_token_start_loc,\n        lora_ids,\n        slice_start_tensor,\n        inputs.stride(0),\n        inputs.stride(1),\n        inputs.stride(2),\n        lora_strides_d0_tensor,\n        lora_strides_d1_tensor,\n        lora_strides_d2_tensor,\n        output_tensor.stride(0),\n        output_tensor.stride(1),\n        hidden_sizes_tensor,\n        BLOCK_M,\n        BLOCK_N,\n        BLOCK_K,\n        EVEN_K,\n        ADD_INPUTS,\n        CAST_TYPE,\n        len(lora_b_weights),\n        same_stride,\n    )"
    },\n    \"vllm/lora/ops/triton_ops/v1/v1_shrink.py\": {\n        \"_v1_shrink_kernel\": \"@triton.jit\\ndef _v1_shrink_kernel(input_ptr, lora_ptr, out_ptr, M, N, K,\\n                      token_indices_sorted_by_lora_ids, num_tokens_per_lora,\\n                      lora_token_start_loc, lora_ids, scaling, input_d0_stride,\\n                      input_d1_stride, lora_d0_stride, lora_d1_stride,\\n                      lora_d2_stride, output_d0_stride, output_d1_stride,\\n                      output_d2_stride, BLOCK_M: tl.constexpr,\\n                      BLOCK_N: tl.constexpr, BLOCK_K: tl.constexpr,\\n                      EVEN_K: tl.constexpr, SPLIT_K: tl.constexpr,\\n                      SLICE_NUM: tl.constexpr):\\n    pid = tl.program_id(axis=0)\\n    pid_mix = tl.program_id(axis=1)\\n    cur_lora_idx = tl.program_id(axis=2)\\n\\n    lora_index = tl.load(lora_ids + cur_lora_idx)\\n    if lora_index == -1:\\n        return\\n\\n    num_tokens = tl.load(num_tokens_per_lora + cur_lora_idx)\\n    if num_tokens == 0:\\n        return\\n\\n    cta_n_num = tl.cdiv(N, BLOCK_N)\\n    pid_m = pid // cta_n_num\\n    pid_n = pid % cta_n_num\\n\\n    if SLICE_NUM == 1:\\n        slice_id: tl.constexpr = 0\\n        pid_sk = pid_mix\\n    else:\\n        slice_id = pid_mix // SPLIT_K\\n        pid_sk = pid_mix % SPLIT_K\\n\\n    if pid_m * BLOCK_M >= num_tokens:\\n        return\\n\\n    token_start_loc = tl.load(lora_token_start_loc + cur_lora_idx)\\n\\n    cta_m_len = min(BLOCK_M, num_tokens - (pid_m * BLOCK_M))\\n    cta_m_offset = token_start_loc + (pid_m * BLOCK_M)\\n    offset_m = tl.arange(0, BLOCK_M)\\n    ram = tl.load(\\n        token_indices_sorted_by_lora_ids + cta_m_offset +\\n        tl.max_contiguous(tl.multiple_of(offset_m % cta_m_len, BLOCK_M),\\n                          BLOCK_M))\\n\\n    do_shrink_kernel(\\n        pid_n,\\n        pid_sk,\\n        slice_id,\\n        lora_index,\\n        input_ptr,\\n        lora_ptr,\\n        out_ptr,\\n        N,\\n        K,\\n        cta_m_len,\\n        ram,\\n        # input strides\\n        input_d0_stride,\\n        input_d1_stride,\\n        # lora strides\\n        lora_d0_stride,\\n        lora_d1_stride,\\n        lora_d2_stride,\\n        # output strides\\n        output_d0_stride,\\n        output_d1_stride,\\n        output_d2_stride,\\n        scaling,\\n        BLOCK_M,\\n        BLOCK_N,\\n        BLOCK_K,\\n        EVEN_K,\\n        SPLIT_K,\\n        SLICE_NUM)\",\n        \"_v1_shrink\": \"@torch.inference_mode()\\ndef _v1_shrink(\\n    inputs: torch.Tensor,  #  shape [num_tokens, hidden_size]\\n    lora_a_weights: List[\\n        torch.Tensor],  # shape [num_loras, lora_rank, hidden_size]\\n    output_tensor: torch.Tensor,  # shape [num_slices, num_tokens, lora_rank]\\n    token_lora_mapping: torch.Tensor,  # shape [num_tokens]\\n    token_indices_sorted_by_lora_ids: torch.Tensor,  # shape [num_tokens] \\n    num_tokens_per_lora: torch.Tensor,  # shape [max-loras + 1]\\n    lora_token_start_loc: torch.Tensor,  # shape [max-loras + 2]\\n    lora_ids: torch.Tensor,  # shape [max-loras + 1]\\n    scaling: float,\\n) -> None:\\n    assert inputs.dtype == lora_a_weights[0].dtype\\n    assert inputs.dtype in [torch.float16, torch.bfloat16]\\n    for weight in lora_a_weights:\\n        assert weight.dtype in [torch.float16, torch.bfloat16]\\n\\n    num_tokens = token_lora_mapping.size(0)\\n    assert inputs.size(0) == num_tokens\\n    assert inputs.size(1) == lora_a_weights[0].size(-1)\\n    assert inputs.is_contiguous()\\n    assert output_tensor.is_contiguous()\\n\\n    (lora_ptr_tensor, lora_strides_d0, lora_strides_d1,\\n     lora_strides_d2) = _get_lora_a_ptr(lora_a_weights, inputs.device)\\n\\n    N, K = lora_a_weights[0].shape[-2:]  # K=hidden_size, N=rank\\n    BLOCK_M = 32\\n    BLOCK_N = 16\\n    BLOCK_K = 32\\n    SPLIT_K = 8\\n    EVEN_K = K % (BLOCK_K * SPLIT_K) == 0\\n\\n    max_tokens_per_lora = torch.max(num_tokens_per_lora).item()\\n    grid = (\\n        triton.cdiv(max_tokens_per_lora, BLOCK_M) * triton.cdiv(N, BLOCK_N),\\n        SPLIT_K * len(lora_a_weights),\\n        lora_ids.size(0),\\n    )\\n    _v1_shrink_kernel[grid](\\n        inputs,\\n        lora_ptr_tensor,\\n        output_tensor,\\n        num_tokens,\\n        N,\\n        K,\\n        token_indices_sorted_by_lora_ids,\\n        num_tokens_per_lora,\\n        lora_token_start_loc,\\n        lora_ids,\\n        scaling,\\n        inputs.stride(0),\\n        inputs.stride(1),\\n        lora_strides_d0,\\n        lora_strides_d1,\\n        lora_strides_d2,\\n        output_tensor.stride(0),\\n        output_tensor.stride(1),\\n        output_tensor.stride(2),\\n        BLOCK_M,\\n        BLOCK_N,\\n        BLOCK_K,\\n        EVEN_K,\\n        SPLIT_K,\\n        len(lora_a_weights),\\n    )\"\n    }\n}\nEOF\n"}

